// 原任职历史、本人生命与新职责资格逐具名代理事实前核，今日持有人不能倒填旧委任。
#pragma once
#include "political_governance_agency_rules.hpp"
#include "resident/domains/politics/governance_agency_intents/political_governance_agency_authored.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include "resident/domains/politics/politics_internal.hpp"
#include "resident/domains/politics/political_member_history.hpp"
