namespace hanmo::resident::governance_agency_detail {
// 边界须本账真实来源；原Office的每个变化同时满足分配序/Common序与tick同侧。
// 原Office账唯一重放，strict phase仅允许本半日后发原变更；不临时改Common时钟。
inline Outcome<Integer> historical_through(const PoliticalGovernanceAgencyContext& x){const auto tick=x.common.tick();if(!x.phase)return {true,tick,{}};if(tick<0||tick==std::numeric_limits<Integer>::max()||x.phase->from_tick!=tick||x.phase->to_tick!=tick+1)return {false,{},common_failure("PoliticalGovernanceAgencyPhaseMismatch").error};return {true,x.phase->to_tick,{}};}
inline Status office_before(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyOffer& offer,Integer tick,const StableId& boundary){
 auto through=historical_through(x);if(!through.ok)return {false,{},through.error};const auto* head=x.common.state().facts.find(boundary);auto cutoff=head?political_governance_agency_fact_sequence(x.common,boundary,head->kind):std::nullopt;const auto& order=x.common.state().facts.order();auto end=std::find(order.begin(),order.end(),boundary);const auto* initial=x.organization_catalog.offices.find(offer.office_id);const auto* current=x.organizations.offices.find(offer.office_id);
 if(!cutoff||end==order.end()||tick<0||tick>x.common.tick()||!initial||!current||initial->organization_id!=offer.organization_id||current->organization_id!=offer.organization_id)return common_failure("PoliticalGovernanceAgencyBoundaryRequired",boundary);
 auto holder=initial->holder_actor_id,at_holder=holder;Integer epoch=initial->epoch,at_epoch=epoch,previous=0,previous_tick=0;auto previous_position=order.end();
 for(const auto& row:x.organizations.facts.rows()){const auto& f=row.second;if(f.kind!="organization_office_changed"||f.office_id!=offer.office_id)continue;auto n=organization_instance_sequence(row.first,"organization");auto at=std::find(order.begin(),order.end(),row.first);const auto* h=x.common.state().facts.find(row.first);
  if(f.id!=row.first||f.organization_id!=offer.organization_id||!n||*n<=previous||*n>=x.common.state().next_instance_id||*n==*cutoff||!h||h->id!=row.first||h->kind!=f.kind||h->domain!="organization"||at==order.end()||(previous_position!=order.end()&&at<=previous_position)||(*n<*cutoff)!=(at<end)||f.tick<previous_tick||f.tick>through.value||(at<end?f.tick>tick:f.tick<tick)||epoch==std::numeric_limits<Integer>::max())return common_failure("PoliticalGovernanceAgencyOfficeOrderMismatch",row.first);
  ++epoch;holder=f.actor_id.empty()?std::nullopt:std::optional<StableId>{f.actor_id};if(at<end){at_epoch=epoch;at_holder=holder;}previous=*n;previous_tick=f.tick;previous_position=at;
 }
 return epoch==current->epoch&&holder==current->holder_actor_id&&at_epoch==offer.office_epoch&&at_holder==std::optional<StableId>{offer.issuer_actor_id}?common_success():common_failure("PoliticalGovernanceAgencyHistoricalPrincipalMismatch",offer.id);
}
// 固定两个原Grant都必须覆盖此时刻；许可终止不抹掉此前真实批准。
inline Status grant_at(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyPolicy& p,Integer tick){for(const auto& id:{p.appointment_grant_id,p.commission_grant_id}){const auto* g=x.organization_catalog.grants.find(id);if(!g||g->valid_from>tick||(g->valid_until&&tick>*g->valid_until))return common_failure("PoliticalGovernanceAgencyGrantExpired",id);}return common_success();}
// 当前人与历史人物分别走原生命读；历史当面行为以永久业务事实见证，未声称全位置重放。
inline Status person_before(const PoliticalGovernanceAgencyContext& x,const StableId& actor,Integer tick,const StableId& id,const StableId& org){auto p=read_actor_presence_before_fact(x.common,x.common_catalog,x.death_origin,actor,tick,id,x.phase);if(!p.ok)return {false,{},p.error};const auto* a=x.common.state().actors.find(actor);constexpr Integer bound=2147483647;if(!p.value.alive||!a||!a->birth_tick||*a->birth_tick< -bound||tick<0||tick>bound||*a->birth_tick>tick||tick-*a->birth_tick<18*720)return common_failure("PoliticalGovernanceAgencyAdultAliveRequired",actor);return validate_political_historical_member_duty(x.common,x.organizations,x.organization_catalog,{org,{},0,actor},tick,id,PoliticalMemberHistoryUse::political_governance_agency,x.phase);}
// 受控本人来源只用于本次签字者，不把亲属/接续本身解释为任何公权。
inline Status player_before(const PoliticalGovernanceAgencyContext& x,const StableId& actor,Integer tick,const StableId& id){if(const auto* origin=x.state.authored_origins.find(id)){if(x.state.version!=2||!x.intents)return common_failure("GovernanceAgencyIntentHistoryRequired",id);return validate_political_governance_agency_authored_source(x.common,x.state,*x.intents,*origin,id,x.player_before);}if(!x.player_before)return common_failure("PoliticalGovernanceAgencyPlayerHistoryRequired");auto p=x.player_before(tick,id);if(!p.ok)return {false,{},p.error};return p.value==actor?common_success():common_failure("PoliticalGovernanceAgencyHistoricalPlayerMismatch",id);}
// 原职位本人和代理必须各自具备当下新职责资格，原受领任务并不由此取消。
inline Status person_current(const PoliticalGovernanceAgencyContext& x,const StableId& actor,const StableId& org,const StableId& site_id,bool at_seat=true){auto valid=politics_detail::available(x.common,x.activity,actor);if(!valid.ok)return valid;valid=growth_independent_office_age(x.common,actor);if(!valid.ok)return valid;OrganizationAccess members(x.common,x.organizations,x.organization_catalog,x.economy);if(!members.actor_accepts_duty(actor,org))return common_failure("PoliticalGovernanceAgencyMemberUnavailable",actor);if(at_seat){const auto* a=x.common.actor(actor);const auto* p=a?std::get_if<SettlementLocation>(&a->location):nullptr;if(!p||p->place_id!=site_id||x.activity.in_interaction(actor))return common_failure("PoliticalGovernanceAgencySeatRequired",actor);}return common_success();}
// 首版只接原初稳定辖区；辖区版本或资金/座所变更须另具名委任，不把今日状态倒填旧签字。
inline Status original_jurisdiction_current(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyPolicy& p){const auto* now=x.politics.jurisdictions.find(p.jurisdiction_id);const auto* old=x.politics_catalog.jurisdictions.find(p.jurisdiction_id);if(!now||!old||std::tie(now->revision,now->seat_place_id,now->political_organization_id,now->controlling_organization_id,now->office_id,now->public_wallet_id,now->public_inventory_ids)!=std::tie(old->revision,old->seat_place_id,old->political_organization_id,old->controlling_organization_id,old->office_id,old->public_wallet_id,old->public_inventory_ids))return common_failure("PoliticalGovernanceAgencyOriginalJurisdictionRequired",p.id);return common_success();}
// 本任旧权源须仍有效；不利用后任今日Office或副手自动递补续签旧代理。
inline Status office_current(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyOffer& o,const StableId& kind){const auto* p=x.catalog.policies.find(o.policy_id);const auto* j=p?x.politics.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* office=x.organizations.offices.find(o.office_id);if(!p||!j||j->revision!=o.jurisdiction_revision||j->political_organization_id!=o.organization_id||j->controlling_organization_id!=o.organization_id||!office||office->deputy_actor_id)return common_failure("PoliticalGovernanceAgencyPrincipalChanged",o.id);auto scope=original_jurisdiction_current(x,*p);if(!scope.ok)return scope;auto v=check_authority(x.common,x.organizations,x.organization_catalog,{o.organization_id,o.office_id,o.office_epoch,o.issuer_actor_id},kind,{ScopeRef::Kind::site,j->seat_place_id},0);return v.ok?grant_at(x,*p,x.common.tick()):Status{false,{},v.error};}
// 回答和撤回可按原事实前界筛选；没有任意传入序号/时间的开放历史读。
inline const PoliticalGovernanceAgencyAnswer* answer(const PoliticalGovernanceAgencyState& s,const StableId& offer){for(const auto& row:s.answers.rows())if(row.second.offer_fact_id==offer)return &row.second;return nullptr;}
inline const PoliticalGovernanceAgencyRevocation* revoked(const PoliticalGovernanceAgencyState& s,const StableId& offer){for(const auto& row:s.revocations.rows())if(row.second.offer_fact_id==offer)return &row.second;return nullptr;}
}
